var config = $("Config").first().json;
var apifyToken = config.APIFY_API_TOKEN || '';
var maxPages = config.MAX_PAGES || 50;

// AUSactive directory - paginated list of registered fitness professionals
// URL pattern: https://directory.ausactive.org.au/directory/professionals?page=N
// Each page has ~20 profiles

var startUrls = [];
for (var p = 1; p <= maxPages; p++) {
  startUrls.push({
    url: 'https://directory.ausactive.org.au/directory/professionals?page=' + p
  });
}

var runRes = null;
var runError = '';
try {
  runRes = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.apify.com/v2/acts/apify~cheerio-scraper/runs?token=' + apifyToken,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      startUrls: startUrls,
      pageFunction: 'async function pageFunction(context) {\n  var $ = context.$;\n  var results = [];\n  var cards = $(".directory-listing__item, .member-card, .professional-card, article, .listing-item");\n  if (cards.length === 0) {\n    cards = $(\'[class*="member"],[class*="profile"],[class*="listing"],[class*="card"]\');\n  }\n  cards.each(function() {\n    var el = $(this);\n    var name = el.find(\'[class*="name"],h2,h3,h4\').first().text().trim();\n    var location = el.find(\'[class*="location"],[class*="suburb"],[class*="city"]\').first().text().trim();\n    var specialty = el.find(\'[class*="specialty"],[class*="specialisation"],[class*="discipline"],[class*="category"]\').first().text().trim();\n    var profileLink = el.find(\'a\').attr(\'href\') || \'\';\n    if (profileLink && !profileLink.startsWith(\'http\')) {\n      profileLink = \'https://directory.ausactive.org.au\' + profileLink;\n    }\n    if (name) {\n      results.push({ name: name, location: location, specialty: specialty, profileLink: profileLink, sourcePage: context.request.url });\n    }\n  });\n  if (results.length === 0) {\n    var allLinks = [];\n    $(\'a[href*="/directory/"]\').each(function() {\n      var href = $(this).attr(\'href\') || \'\';\n      var text = $(this).text().trim();\n      if (href.indexOf(\'/professionals/\') !== -1 && text) {\n        var fullHref = href.startsWith(\'http\') ? href : \'https://directory.ausactive.org.au\' + href;\n        allLinks.push({ name: text, profileLink: fullHref, location: \'\', specialty: \'\', sourcePage: context.request.url });\n      }\n    });\n    return allLinks;\n  }\n  return results;\n}',
      maxConcurrency: 3,
      maxRequestsPerCrawl: maxPages + 10,
      proxyConfiguration: { useApifyProxy: true }
    })
  });
} catch (e) {
  runError = e.message || String(e);
}

if (runError || !runRes) {
  return [{ json: { status: 'Scraper failed to start: ' + runError, runId: '', datasetId: '' } }];
}

var runData = runRes.data || runRes;
var runId = runData.id || '';
var datasetId = runData.defaultDatasetId || '';

return [{ json: {
  status: 'AUSactive scraper started',
  runId: runId,
  datasetId: datasetId,
  pagesQueued: maxPages
} }];

var config = $("Config").first().json;
var apifyToken = config.APIFY_API_TOKEN || '';
var prev = $input.first().json;
var runId = prev.runId || '';
var datasetId = prev.datasetId || '';

if (!runId) {
  return [{ json: { status: prev.status || 'No run to check', profiles: [], profileCount: 0 } }];
}

// Check run status
var runStatus = '';
try {
  var statusRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.apify.com/v2/actor-runs/' + runId + '?token=' + apifyToken
  });
  var statusData = statusRes.data || statusRes;
  runStatus = statusData.status || '';
  if (!datasetId) { datasetId = statusData.defaultDatasetId || ''; }
} catch (e) {
  return [{ json: { status: 'Could not check run status: ' + e.message, profiles: [], profileCount: 0 } }];
}

if (runStatus !== 'SUCCEEDED') {
  return [{ json: { status: 'Run not complete yet - status: ' + runStatus + '. Re-run this workflow or wait longer.', profiles: [], profileCount: 0, runId: runId, datasetId: datasetId } }];
}

// Fetch all results
var allProfiles = [];
var offset = 0;
var limit = 200;
var keepFetching = true;

while (keepFetching) {
  try {
    var dataRes = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.apify.com/v2/datasets/' + datasetId + '/items?token=' + apifyToken + '&limit=' + limit + '&offset=' + offset
    });
    var items = Array.isArray(dataRes) ? dataRes : [];
    for (var i = 0; i < items.length; i++) {
      allProfiles.push(items[i]);
    }
    if (items.length < limit) {
      keepFetching = false;
    } else {
      offset += limit;
    }
  } catch (e) {
    keepFetching = false;
  }
}

// Clean and deduplicate
var seen = {};
var cleaned = [];
for (var j = 0; j < allProfiles.length; j++) {
  var p = allProfiles[j];
  if (!p.name) { continue; }
  var key = (p.name || '').toLowerCase().trim();
  if (seen[key]) { continue; }
  seen[key] = true;
  cleaned.push({
    name: (p.name || '').trim(),
    location: (p.location || '').trim(),
    specialty: (p.specialty || '').trim(),
    profileLink: p.profileLink || '',
    sourcePage: p.sourcePage || ''
  });
}

return [{ json: {
  status: 'Scrape complete - ' + cleaned.length + ' unique profiles found',
  profiles: cleaned,
  profileCount: cleaned.length,
  runId: runId,
  datasetId: datasetId
} }];

var config = $("Config").first().json;
var prev = $input.first().json;
var profiles = prev.profiles || [];

if (profiles.length === 0) {
  return [{ json: { status: prev.status, imported: 0, skipped: 0, failed: 0 } }];
}

var ghlHeaders = {
  'Authorization': 'Bearer ' + config.GHL_API_TOKEN,
  'Content-Type': 'application/json',
  'Version': '2021-07-28'
};

var today = new Date().toISOString().split('T')[0];
var imported = 0;
var skipped = 0;
var failed = 0;
var importedNames = [];

for (var i = 0; i < profiles.length; i++) {
  var profile = profiles[i];
  var fullName = profile.name || 'Unknown';
  var parts = fullName.trim().split(/\s+/);
  var firstName = parts[0] || 'Unknown';
  var lastName = parts.slice(1).join(' ') || '';

  // Check if already in GHL by name
  var existingCount = 0;
  try {
    var searchRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://services.leadconnectorhq.com/contacts/search',
      headers: ghlHeaders,
      body: JSON.stringify({
        locationId: config.GHL_LOCATION_ID,
        searchAfter: [fullName.toLowerCase()],
        filters: [{ field: 'firstName', operator: 'contains', value: firstName }],
        pageLimit: 5
      })
    });
    existingCount = (searchRes.contacts || []).length;
  } catch (e) {
    existingCount = 0;
  }

  if (existingCount > 0) {
    skipped++;
    continue;
  }

  var tags = [
    'source:ausactive-directory',
    'new-lead',
    'phase-1-import',
    'bio-qualified',
    'batch:' + today
  ];
  if (profile.location) { tags.push('location:' + profile.location.toLowerCase().replace(/\s+/g, '-')); }
  if (profile.specialty) { tags.push('specialty:' + profile.specialty.toLowerCase().replace(/\s+/g, '-').substring(0, 30)); }

  var noteText = '=== AUSactive Directory Import ===\nImported: ' + today + '\nFull Name: ' + fullName + '\nLocation: ' + (profile.location || 'N/A') + '\nSpecialty: ' + (profile.specialty || 'N/A') + '\nAUSactive Profile: ' + (profile.profileLink || 'N/A') + '\nSource Page: ' + (profile.sourcePage || 'N/A');

  var contactId = '';
  try {
    var createRes = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://services.leadconnectorhq.com/contacts/',
      headers: ghlHeaders,
      body: JSON.stringify({
        firstName: firstName,
        lastName: lastName,
        locationId: config.GHL_LOCATION_ID,
        source: 'ausactive-directory',
        tags: tags
      })
    });
    var contact = createRes.contact || createRes;
    contactId = contact.id || '';
  } catch (e) {
    failed++;
    continue;
  }

  if (contactId) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://services.leadconnectorhq.com/contacts/' + contactId + '/notes',
        headers: ghlHeaders,
        body: JSON.stringify({ body: noteText })
      });
    } catch (e) {}

    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://services.leadconnectorhq.com/opportunities/',
        headers: ghlHeaders,
        body: JSON.stringify({
          pipelineId: config.GHL_PIPELINE_ID,
          locationId: config.GHL_LOCATION_ID,
          pipelineStageId: config.GHL_STAGE_IDENTIFIED_ID,
          contactId: contactId,
          name: firstName + ' ' + lastName + ' - Discovery',
          status: 'open'
        })
      });
    } catch (e) {}

    imported++;
    importedNames.push(fullName);
  }

  // Small delay to avoid GHL rate limits
  await new Promise(function(resolve) { setTimeout(resolve, 300); });
}

return [{ json: {
  status: 'AUSactive import complete',
  imported: imported,
  skipped: skipped,
  failed: failed,
  total: profiles.length,
  runDate: today
} }];
